@functools.lru_cache
def fibonacci(n):
    if n < 2:
        return n
    return fibonacci(n-1) + fibonacci(n-2)

import time

def timer(func):
    def wrapper(*args):
        start = time.time()
        result = func(*args)
        end = time.time()
        print(f'{func.__name__}: {end-start:.4f}s')
        return result
    return wrapper

@timer
def slow_function():
    time.sleep(1)
    return 'done'

# مثال ۱: لاگ کردن فراخوانی تابع
def log_calls(func):
    def wrapper(*args, **kwargs):
        print(f'📞 فراخوانی: {func.__name__}({args}, {kwargs})')
        result = func(*args, **kwargs)
        print(f'✅ نتیجه: {result}')
        return result
    return wrapper

@log_calls
def add(a, b):
    return a + b

add(3, 5)
# 📞 فراخوانی: add((3, 5), {})
# ✅ نتیجه: 8

# مثال ۲: بررسی دسترسی کاربر
def require_admin(func):
    def wrapper(user, *args, **kwargs):
        if user.get('is_admin'):
            return func(user, *args, **kwargs)
        else:
            print('⛔ دسترسی غیرمجاز!')
            return None
    return wrapper

@require_admin
def delete_post(user, post_id):
    print(f'🗑️ پست {post_id} حذف شد')

admin = {'name': 'Ali', 'is_admin': True}
guest = {'name': 'Sara', 'is_admin': False}

delete_post(admin, 42)   # 🗑️ پست 42 حذف شد
delete_post(guest, 42)   # ⛔ دسترسی غیرمجاز!

