def double_result(func):
    def wrapper(*args):
        return func(*args) * 2
    return wrapper

@double_result
def square(x):
    return x * x

print(square(5))

def log(func):
    def wrapper(*args, **kwargs):
        print(f'calling {func.__name__}')
        result = func(*args, **kwargs)
        print(f'{func.__name__} returned {result}')
        return result
    return wrapper

@log
def multiply(a, b):
    return a * b

print(multiply(3, 4))

